INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Projektmitarbeiter eine wichtige Rolle im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Führen Aufgaben aus"}, {"text": "Nein", "correct": false, "because": "Sie sind zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen Projektmitarbeiter?', 3, '[{"text": "Projektziele durch Aufgaben umsetzen", "correct": true, "because": "Setzen Plan in die Tat"}, {"text": "Projektziele definieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Projekt finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektmitarbeiter führen Arbeitspakete aus. b) Sie entscheiden über das Budget.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Auftraggeberaufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernehmen Projektmitarbeiter?', 4, '[{"text": "Ausführung von Arbeitspaketen", "correct": true, "because": "Setzen Plan um"}, {"text": "Unklare Tätigkeiten", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Berichterstattung an Projektleiter", "correct": true, "because": "Informieren über Fortschritt"}, {"text": "Fachliche Umsetzung", "correct": true, "because": "Nutzen Kompetenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Projektmitarbeiter erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Ausführung fehlt"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Projektmitarbeiter in der Durchführung?', 3, '[{"text": "Umsetzung der geplanten Aufgaben", "correct": true, "because": "Realisieren Projekt"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Projekt direkt finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Projektmitarbeiter nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Universelle Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung haben Projektmitarbeiter?', 3, '[{"text": "Pünktliche und qualitativ hochwertige Arbeit", "correct": true, "because": "Sichern Ergebnisse"}, {"text": "Gesamtplanung übernehmen", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Budget allein festlegen", "correct": false, "because": "Auftraggeberaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektmitarbeiter arbeiten nach Anweisung. b) Sie definieren die Projektziele.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Auftraggeberaufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Projektmitarbeiter?', 3, '[{"text": "Projekt bleibt unvollendet", "correct": true, "because": "Ausführung fehlt"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Stillstand"}, {"text": "Kosten sinken", "correct": false, "because": "Plan nutzlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Projektleiter ohne Projektmitarbeiter arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Team für Umsetzung nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Aufgabe eines Projektmitarbeiters?', 3, '[{"text": "Testskript gemäß Plan erstellen", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas machen", "correct": false, "because": "Zu vage"}, {"text": "Team soll planen", "correct": false, "because": "Keine Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Projektmitarbeiter nur für technische Aufgaben zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Aufgaben"}, {"text": "Ja", "correct": false, "because": "Breitere Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Projektmitarbeiter?', 4, '[{"text": "Fachkompetenz", "correct": true, "because": "Sichern Qualität"}, {"text": "Unklare Rollen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Teamarbeit", "correct": true, "because": "Fördern Zusammenarbeit"}, {"text": "Zugeteilte Aufgaben", "correct": true, "because": "Definieren Verantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Projektmitarbeiter ihren Fortschritt melden?', 2, '[{"text": "Ja", "correct": true, "because": "Projektleiter braucht Rückmeldung"}, {"text": "Nein", "correct": false, "because": "Kontrolle wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Projektmitarbeiter im Controlling?', 3, '[{"text": "Fortschritt an Projektleiter melden", "correct": true, "because": "Unterstützen Steuerung"}, {"text": "Projektziele neu setzen", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Team finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projektmitarbeiter ohne Anweisungen arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Projektleiter steuert"}, {"text": "Ja", "correct": false, "because": "Unkoordiniert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Arbeit der Projektmitarbeiter?', 3, '[{"text": "Unklare Anweisungen", "correct": true, "because": "Verhindern Umsetzung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Arbeit"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektmitarbeiter unterstützen den Erfolg. b) Sie entscheiden über Ziele.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Auftraggeberaufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Projektmitarbeiter?', 3, '[{"text": "Effektive Aufgabenbearbeitung", "correct": true, "because": "Fördert Projektfortschritt"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Umsetzung", "correct": false, "because": "Fördert Ergebnisse"}]');
